# check for repeated identical value runs (flatline)
import itertools
def longest_const_run(tsid):
    s=sorted(vals[tsid].items())
    best=1; cur=1
    for i in range(1,len(s)):
        if abs(s[i][1]-s[i-1][1])<1e-9: cur+=1; best=max(best,cur)
        else: cur=1
    return best, len(s)

